 static KahluaTable makeup(String name,String loc){var location=locations.computeIfAbsent(loc,k->{var v=ItemBodyLocation.register("sao_residual:"+k);BodyLocations.getGroup("ResidualProof").getOrCreateLocation(v);return v;});var actual=identified(new InventoryItem("Proof",name,name,"Item_None"));var t=p.newTable();items.put(t,actual);t.rawset("getBodyLocation",(JavaFunction)(f,n)->f.push(location));t.rawset("getName",(JavaFunction)(f,n)->f.push(name));t.rawset("getType",(JavaFunction)(f,n)->f.push(name));return t;}
