 static int body(LuaCallFrame f){try{var actor=(IsoPlayer)unsafe.allocateInstance(IsoPlayer.class);field(actor,IsoGameCharacter.class,"stats",new Stats());return f.push(new BodyDamage(actor));}catch(Exception e){throw new RuntimeException(e);}}
