  zombie.ui.UIManager.defaultthread=thread;LuaManager.platform=p;LuaManager.converterManager=new KahluaConverterManager();zombie.Lua.KahluaNumberConverter.install(LuaManager.converterManager);LuaManager.exposer=new LuaManager.Exposer(LuaManager.converterManager,p,env);LuaManager.caller=new se.krka.kahlua.integration.LuaCaller(LuaManager.converterManager);
