  for(Class<?> c:new Class<?>[]{InventoryItem.class,ItemContainer.class,InventoryContainer.class,DrainableComboItem.class,HandWeapon.class,Literature.class,Stats.class,CharacterStat.class,CharacterTraits.class,CharacterTrait.class,BodyDamage.class,BodyPart.class,java.util.ArrayList.class,ItemBodyLocation.class,ItemTag.class,zombie.iso.IsoObject.class,zombie.iso.IsoGridSquare.class,WeaponType.class,zombie.core.ImmutableColor.class}){LuaManager.exposer.setExposed(c);LuaManager.exposer.exposeLikeJava(c,env);}
  var squares=new IdentityHashMap<KahluaTable,zombie.iso.IsoGridSquare>();
  env.rawset("nativeSquare",(JavaFunction)(f,n)->{var sq=new zombie.iso.IsoGridSquare(null,null,10,20,0);var host=p.newTable();squares.put(host,sq);host.rawset("AddTileObject",(JavaFunction)(q,z)->{sq.getObjects().add((zombie.iso.IsoObject)q.get(1));return 0;});host.rawset("nativeCount",(JavaFunction)(q,z)->q.push((double)sq.getObjects().size()));host.rawset("nativeOwns",(JavaFunction)(q,z)->q.push(((zombie.iso.IsoObject)q.get(1)).getSquare()==sq));return f.push(host);});
  env.rawset("nativePuddle",(JavaFunction)(f,n)->{var sq=squares.get((KahluaTable)f.get(0));if(sq==null)throw new AssertionError("D2_RESIDUAL:puddle_constructor_exact_square");return f.push(new zombie.iso.IsoObject(sq,(String)f.get(1)));});
