  env.rawset("nativeItem",(JavaFunction)(f,n)->f.push(identified(new InventoryItem("Base",(String)f.get(0),(String)f.get(0),"Item_None"))));
  env.rawset("nativeNeedle",(JavaFunction)(f,n)->{var script=new Item();var module=new ScriptModule();module.name="Proof";script.setModule(module);script.setName("Needle");var i=new DrainableComboItem("Proof","Needle","Needle",script);i.setUseDelta(.1f);i.setUsedDelta(1f);return f.push(i);});
  env.rawset("nativeMakeup",(JavaFunction)(f,n)->f.push(makeup((String)f.get(0),(String)f.get(1))));
  env.rawset("nativeWearer",(JavaFunction)(f,n)->{var worn=new WornItems(BodyLocations.getGroup("ResidualProof"));var t=p.newTable();var inv=new ItemContainer();var hostInv=inventory(inv);t.rawset("getInventory",(JavaFunction)(q,z)->q.push(hostInv));t.rawset("getWornItem",(JavaFunction)(q,z)->{var actual=worn.getItem((ItemBodyLocation)q.get(1));for(var row:items.entrySet())if(row.getValue()==actual)return q.push(row.getKey());return q.push(null);});t.rawset("setWornItem",(JavaFunction)(q,z)->{worn.setItem((ItemBodyLocation)q.get(1),item(q.get(2)));return 0;});t.rawset("removeWornItem",(JavaFunction)(q,z)->{worn.remove(item(q.get(1)));return 0;});t.rawset("nativeAdd",(JavaFunction)(q,z)->{inv.AddItem(item(q.get(1)));return 0;});t.rawset("nativeContains",(JavaFunction)(q,z)->q.push(inv.contains(item(q.get(1)))));t.rawset("nativeWornCount",(JavaFunction)(q,z)->q.push((double)worn.size()));return f.push(t);});
  env.rawset("nativeBody",(JavaFunction)(f,n)->body(f));
